    const names = [...m[3]!.matchAll(/\s+([\w:-]+)=/g)].map((x) => x[1]);
    assert.equal(new Set(names).size, names.length, `duplicate attribute in ${m[0]}`);
    if (m[1]) assert.equal(stack.pop(), m[2], `mismatched </${m[2]}>`);
